import fs from 'node:fs';
import { promisify } from 'node:util';

// Callback style: nesting grows with each step
fs.readFile('a.json', 'utf8', (err, a) => {
  if (err) return console.error(err);
  fs.readFile('b.json', 'utf8', (err, b) => {
    if (err) return console.error(err);
    fs.writeFile('c.json', a + b, (err) => {
      if (err) return console.error(err);
      console.log('done');
    });
  });
});

// Flat equivalent
const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);
try {
  const a = await readFile('a.json', 'utf8');
  const b = await readFile('b.json', 'utf8');
  await writeFile('c.json', a + b);
  console.log('done');
} catch (err) {
  console.error(err);
}

import { setTimeout as sleep } from 'node:timers/promises';

const ok = (v, ms) => sleep(ms, v);
const fail = (ms) => sleep(ms).then(() => { throw new Error('fail'); });

console.log(await Promise.all([ok('a', 30), ok('b', 10)]));          // [ 'a', 'b' ]
console.log(await Promise.race([ok('slow', 50), ok('fast', 10)]));   // fast
console.log(await Promise.any([fail(5), ok('winner', 20)]));         // winner

const results = await Promise.allSettled([ok(1, 5), fail(5)]);
console.log(results.map((r) => r.status));    // [ 'fulfilled', 'rejected' ]

import { setTimeout as sleep } from 'node:timers/promises';

const load = async (id) => { await sleep(100); return id * 2; };

console.time('sequential');
for (const id of [1, 2, 3]) await load(id);
console.timeEnd('sequential');            // ~300ms

console.time('parallel');
console.log(await Promise.all([1, 2, 3].map(load)));   // [ 2, 4, 6 ]
console.timeEnd('parallel');              // ~100ms

// process in batches of 2 to cap concurrency
const ids = [1, 2, 3, 4, 5];
const out = [];
for (let i = 0; i < ids.length; i += 2) {
  out.push(...await Promise.all(ids.slice(i, i + 2).map(load)));
}
console.log(out);                         // [ 2, 4, 6, 8, 10 ]

async function retry(fn, tries = 3) {
  for (let n = 1; ; n++) {
    try { return await fn(); }
    catch (err) {
      if (n === tries) throw err;
      await sleep(2 ** n * 50);
    }
  }
}

