import { createReadStream } from 'node:fs';

let bytes = 0;
for await (const chunk of createReadStream('big.iso')) {
  bytes += chunk.length;          // each chunk is a Buffer (~64 KB)
}
console.log(bytes, 'bytes, memory stayed small');

import { createWriteStream } from 'node:fs';
import { once } from 'node:events';

const out = createWriteStream('big.txt');

for (let i = 0; i < 1_000_000; i++) {
  const ok = out.write(`line ${i}\n`);
  if (!ok) await once(out, 'drain');     // wait until the buffer empties
}
out.end();
await once(out, 'finish');
console.log('written');

import { createReadStream, createWriteStream } from 'node:fs';
import { createGzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';

try {
  await pipeline(
    createReadStream('access.log'),
    async function* (source) {
      for await (const chunk of source) {
        yield chunk.toString().replaceAll('password=', 'password=***');
      }
    },
    createGzip(),
    createWriteStream('access.log.gz'),
  );
  console.log('done');
} catch (err) {
  console.error('pipeline failed:', err.code ?? err.message);
}

