import { setImmediate as yieldLoop } from 'node:timers/promises';

function isPrime(n) {
  for (let i = 2; i * i <= n; i++) if (n % i === 0) return false;
  return n > 1;
}

async function countPrimes(limit) {
  let count = 0;
  for (let i = 0; i < limit; i++) {
    if (isPrime(i)) count++;
    if (i % 50_000 === 0) await yieldLoop();   // let other work run
  }
  return count;
}

const ticker = setInterval(() => process.stdout.write('.'), 20);
console.log('\nprimes:', await countPrimes(2_000_000));
clearInterval(ticker);

import http from 'node:http';

const server = http.createServer((req, res) => {
  setTimeout(() => res.end('done\n'), 2000);      // slow request
});
server.listen(3000, () => console.log('listening, pid', process.pid));

let shuttingDown = false;
async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`${signal} received, closing...`);

  const force = setTimeout(() => {
    console.error('forced exit');
    process.exit(1);
  }, 10_000);
  force.unref();

  server.close(async (err) => {
    // await db.close(); await redis.quit();
    console.log('closed cleanly');
    process.exit(err ? 1 : 0);
  });
  server.closeIdleConnections();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
